// src/shared/server/http-error-handler.ts
var HttpErrorHandler = class {
  static handle(error, res, logger25) {
    let errorCode = ErrorCode.INTERNAL_SERVER_ERROR;
    let message = "Internal server error";
    let details;
    let statusCode = 500;
    if (error instanceof CustomError) {
      statusCode = error.statusCode;
      message = error.message;
      if (error.code) {
        errorCode = error.code;
      }
      if (error.code) {
      } else if (error.statusCode === 400) {
        errorCode = ErrorCode.VALIDATION_ERROR;
      } else if (error.statusCode === 401) {
        errorCode = ErrorCode.UNAUTHORIZED;
      } else if (error.statusCode === 404) {
        errorCode = ErrorCode.NOT_FOUND;
      } else if (error.statusCode === 409) {
        errorCode = ErrorCode.CONFLICT;
      } else if (error.statusCode === 403) {
        errorCode = ErrorCode.FORBIDDEN;
      } else if (error.statusCode === 503) {
        errorCode = ErrorCode.SERVICE_UNAVAILABLE;
      }
    } else if (error instanceof BadRequestError) {
      errorCode = ErrorCode.VALIDATION_ERROR;
      message = error.message;
      statusCode = 400;
    } else if (error instanceof ConflicError) {
      errorCode = ErrorCode.CONFLICT;
      message = error.message;
      statusCode = 409;
    } else if (error instanceof NotFoundError) {
      errorCode = ErrorCode.NOT_FOUND;
      message = error.message;
      statusCode = 404;
    } else if (error instanceof ForbiddenError) {
      errorCode = ErrorCode.FORBIDDEN;
      message = error.message;
      statusCode = 403;
    } else if (error instanceof Error && "code" in error && typeof error.code === "string") {
      const appError = error;
      errorCode = appError.code || ErrorCode.INTERNAL_SERVER_ERROR;
      message = error.message;
      statusCode = getStatusCodeFromErrorCode(errorCode);
    } else if (error instanceof Error) {
      message = error.message;
      if (message.includes("Invalid email") || message.includes("Invalid phone")) {
        errorCode = ErrorCode.VALIDATION_ERROR;
        statusCode = 400;
      } else if (message.includes("not found")) {
        errorCode = ErrorCode.NOT_FOUND;
        statusCode = 404;
      } else if (message.includes("already exists")) {
        errorCode = ErrorCode.CONFLICT;
        statusCode = 409;
      }
    } else {
      message = "An unexpected error occurred";
    }
    const errorResponse = ResponseFormatter.error(errorCode, message, details);
    res.status(statusCode).json(errorResponse);
    return errorResponse;
  }
  static handleApplicationError(error, res, logger25) {
    return this.handle(error, res, logger25);
  }
  static validateRequired(data, ...fields) {
    for (const field of fields) {
      if (!data[field]) {
        throw new BadRequestError(`${field.charAt(0).toUpperCase() + field.slice(1)} is required`);
      }
    }
  }
  static validateEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      throw new BadRequestError("Invalid email format");
    }
  }
  static validatePassword(password, minLength = 8) {
    if (password.length < minLength) {
      throw new BadRequestError(`Password must be at least ${minLength} characters`);
    }
  }
};

// src/shared/server/error-middleware.ts
var logger2 = createLogger("ErrorMiddleware");
function errorHandlingMiddleware(err, req, res, next) {
  logger2.error("Request error occurred", err, {
    path: req.path,
    method: req.method,
    query: req.query,
    body: req.body,
    userId: req.userId || "anonymous"
  });
  HttpErrorHandler.handle(err, res, logger2);
}
function asyncHandler(fn) {
  return (req, res, next) => {
    fn(req, res, next).catch((error) => {
      logger2.error("Async handler caught error", error, {
        path: req.path,
        method: req.method
      });
      HttpErrorHandler.handle(error, res, logger2);
    });
  };
}

// src/module/auth/infrastructure/api/auth.api.ts
var AuthAPI = class {
  constructor(authController) {
    this.authController = authController;
    this.initializeRoutes();
  }
  router = express.Router();
  initializeRoutes() {
    this.router.post("/register", asyncHandler(this.register.bind(this)));
    this.router.get("/verify-email", asyncHandler(this.verifyEmail.bind(this)));
    this.router.post("/login", asyncHandler(this.login.bind(this)));
    this.router.post("/logout", asyncHandler(this.logout.bind(this)));
    this.router.post("/forgot-password", asyncHandler(this.forgotPassword.bind(this)));
    this.router.post("/reset-password", asyncHandler(this.resetPassword.bind(this)));
    this.router.post("/refresh-token", asyncHandler(this.refreshToken.bind(this)));
  }
  validateRegisterInput(email, password) {
    HttpErrorHandler.validateRequired({ email, password }, "email", "password");
    HttpErrorHandler.validateEmail(email);
    if (password.length < 6) {
      throw new BadRequestError("Password must be at least 6 characters long");
    }
  }
  async register(req, res, next) {
    const { email, password } = req.body;
    this.validateRegisterInput(email, password);
    const ipAddress = req.ip || req.connection.remoteAddress || "unknown";
    const result = await this.authController.register({ email, password }, ipAddress);
    const response = ResponseFormatter.success(result, result.message);
    res.status(201).json(response);
  }
  async verifyEmail(req, res, next) {
    const { token } = req.query;
    if (!token || typeof token !== "string") {
      throw new BadRequestError("Token is required");
    }
    const result = await this.authController.verifyEmail({ token });
    const response = ResponseFormatter.success(result, result.message);
    res.status(200).json(response);
  }
  async login(req, res, next) {
    const { email, password } = req.body;
    const ipAddress = req.ip || req.connection.remoteAddress || "unknown";
    const deviceInfo = (req.headers["user-agent"] ?? "unknown").slice(0, 500);
    const result = await this.authController.login({ email, password, deviceInfo }, ipAddress);
    const response = ResponseFormatter.success(result, "Login successful");
    res.status(200).json(response);
  }
  async forgotPassword(req, res, next) {
    const { email } = req.body;
    if (!email || typeof email !== "string") {
      throw new BadRequestError("Email is required");
    }
    HttpErrorHandler.validateEmail(email);
    const ipAddress = req.ip || req.connection.remoteAddress || "unknown";
    const result = await this.authController.forgotPassword({ email }, ipAddress);
    const response = ResponseFormatter.success(result, result.message);
    res.status(200).json(response);
  }
  async resetPassword(req, res, next) {
    const { token, newPassword } = req.body;
    if (!token || typeof token !== "string") {
      throw new BadRequestError("Token is required");
    }
    if (!newPassword || typeof newPassword !== "string") {
      throw new BadRequestError("New password is required");
    }
    if (newPassword.length < 6) {
      throw new BadRequestError("Password must be at least 6 characters long");
    }
    const result = await this.authController.resetPassword({ token, newPassword });
    const response = ResponseFormatter.success(result, result.message);
    res.status(200).json(response);
  }
  async logout(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      throw new BadRequestError("Authorization header is required");
    }
    const accessToken = authHeader.slice("Bearer ".length);
    const { refreshToken } = req.body;
    const result = await this.authController.logout({ accessToken, refreshToken });
    const response = ResponseFormatter.success(result, result.message);
    res.status(200).json(response);
  }
  async refreshToken(req, res, next) {
    const { refreshToken } = req.body;
    if (!refreshToken || typeof refreshToken !== "string") {
      throw new BadRequestError("Refresh token is required");
    }
    const result = await this.authController.refreshToken({ refreshToken });
    const response = ResponseFormatter.success(result, "Token refreshed successfully");
    res.status(200).json(response);
  }
};

// src/module/auth/interface-adapter/controller/auth.controller.ts
var AuthController = class {
  constructor(registerUseCaseFactory, verifyEmailUseCase, loginUseCaseFactory, forgotPasswordUseCaseFactory, resetPasswordUseCase, logoutUseCase, refreshTokenUseCase, googleOAuthLoginUseCase) {
    this.registerUseCaseFactory = registerUseCaseFactory;
    this.verifyEmailUseCase = verifyEmailUseCase;
    this.loginUseCaseFactory = loginUseCaseFactory;
    this.forgotPasswordUseCaseFactory = forgotPasswordUseCaseFactory;
    this.resetPasswordUseCase = resetPasswordUseCase;
    this.logoutUseCase = logoutUseCase;
    this.refreshTokenUseCase = refreshTokenUseCase;
    this.googleOAuthLoginUseCase = googleOAuthLoginUseCase;
  }
  async register(command, ipAddress) {
    const registerUseCase = this.registerUseCaseFactory.create(ipAddress);
    const result = await registerUseCase.execute(command);
    return result;
  }
  async verifyEmail(command) {
    const result = await this.verifyEmailUseCase.execute(command);
    return result;
  }
  async login(command, ipAddress) {
    const loginUseCase = this.loginUseCaseFactory.create(ipAddress);
    const result = await loginUseCase.execute(command);
    return result;
  }
  async forgotPassword(command, ipAddress) {
    const useCase = this.forgotPasswordUseCaseFactory.create(ipAddress);
    return useCase.execute(command);
  }
  async resetPassword(command) {
    return this.resetPasswordUseCase.execute(command);
  }
  async logout(command) {
    return this.logoutUseCase.execute(command);
  }
  async refreshToken(command) {
    return this.refreshTokenUseCase.execute(command);
  }
  async googleOAuthLogin(command) {
    return this.googleOAuthLoginUseCase.execute(command);
  }
};

// src/module/auth/applications/utils/rate-limit.helper.ts
var RateLimitHelper = class {
  constructor(rateLimiter) {
    this.rateLimiter = rateLimiter;
  }
  async checkRateLimit(email, ipAddress) {
    if (ipAddress) {
      const isIpLimited = await this.rateLimiter.isRateLimitExceeded(ipAddress);
      if (isIpLimited) {
        throw new RateLimitExceededError();
      }
      await this.rateLimiter.incrementRateLimit(ipAddress);
    }
    const isEmailLimited = await this.rateLimiter.isEmailRateLimitExceeded(email);
    if (isEmailLimited) {
      throw new RateLimitExceededError();
    }
    await this.rateLimiter.incrementEmailRateLimit(email);
  }
};

// src/module/auth/applications/utils/database-error.helper.ts
function isDuplicateEmailError(error) {
  const prismaTarget = Array.isArray(error?.meta?.target) ? error.meta.target.join(",") : String(error?.meta?.target ?? "");
  return (
    // Prisma unique constraint error
    error?.code === "P2002" || prismaTarget.includes("email") || prismaTarget.includes("users_email_key") || typeof error?.message === "string" && (error.message.includes("users_email_key") || error.message.includes("Unique constraint failed") || error.message.includes("email")) || error.code === "ER_DUP_ENTRY" || error.code === 23e3 || error.message && error.message.includes("Duplicate entry")
  );
}

// src/module/auth/applications/usecases/register.usecase.ts
var RegisterUseCase = class {
  constructor(userRepository, passwordHasher, rateLimiter, tokenGenerator, emailVerificationTokenRepository, emailSender, ipAddress) {
    this.userRepository = userRepository;
    this.passwordHasher = passwordHasher;
    this.rateLimiter = rateLimiter;
    this.tokenGenerator = tokenGenerator;
    this.emailVerificationTokenRepository = emailVerificationTokenRepository;
    this.emailSender = emailSender;
    this.ipAddress = ipAddress;
    this.rateLimitHelper = new RateLimitHelper(rateLimiter);
  }
  rateLimitHelper;
  logger = createLogger("RegisterUseCase");
  async execute(command) {
    const { email: emailString, password } = command;
    this.logger.info("Starting user registration", { email: emailString });
    await this.rateLimitHelper.checkRateLimit(emailString, this.ipAddress);
    const hashedPassword = await this.passwordHasher.hash(password);
    const email = new Email(emailString);
    const user = User.registerWithEmail(email, hashedPassword);
    try {
      const savedUser = await this.userRepository.save(user);
      const rawToken = this.tokenGenerator.generateRandomToken(32);
      const tokenHash = this.tokenGenerator.hashToken(rawToken);
      const expiresAt = new Date(Date.now() + 30 * 60 * 1e3);
      const emailVerificationToken = {
        id: "",
        userId: savedUser.id,
        tokenHash,
        expiresAt,
        createdAt: /* @__PURE__ */ new Date()
      };
      await this.emailVerificationTokenRepository.save(emailVerificationToken);
      await this.emailSender.sendEmailVerification(emailString, rawToken);
      this.logger.info("User registered successfully", {
        userId: savedUser.id,
        email: emailString
      });
      return {
        message: "Registration successful. Please verify your email."
      };
    } catch (error) {
      if (isDuplicateEmailError(error)) {
        this.logger.warn("Registration failed: Email already exists", { email: emailString });
        throw new EmailAlreadyExistsError();
      }
      this.logger.error("Registration failed with unexpected error", error, { email: emailString });
      throw error;
    }
  }
};

// src/module/auth/applications/usecases/forgot-password.usecase.ts
var RESET_TOKEN_TTL_MINUTES = 15;
var ForgotPasswordUseCase = class {
  constructor(userRepository, tokenGenerator, passwordResetTokenRepository, emailSender, rateLimiter, ipAddress) {
    this.userRepository = userRepository;
    this.tokenGenerator = tokenGenerator;
    this.passwordResetTokenRepository = passwordResetTokenRepository;
    this.emailSender = emailSender;
    this.rateLimiter = rateLimiter;
    this.ipAddress = ipAddress;
    this.rateLimitHelper = new RateLimitHelper(rateLimiter);
  }
  rateLimitHelper;
  async execute(command) {
    const { email } = command;
    await this.rateLimitHelper.checkRateLimit(email, this.ipAddress);
    const user = await this.userRepository.findByEmail(email);
    if (user && user.id) {
      await this.passwordResetTokenRepository.deleteByUserId(user.id);
      const rawToken = this.tokenGenerator.generateRandomToken(32);
      const tokenHash = this.tokenGenerator.hashToken(rawToken);
      const expiresAt = new Date(Date.now() + RESET_TOKEN_TTL_MINUTES * 60 * 1e3);
      const resetToken = {
        id: "",
        userId: user.id,
        tokenHash,
        expiresAt,
        createdAt: /* @__PURE__ */ new Date()
      };
      await this.passwordResetTokenRepository.save(resetToken);
      await this.emailSender.sendPasswordReset(email, rawToken);
    }
    return {
      message: ""
    };
  }
};

