// src/module/product/applications/usecases/get-related-products-from-orders.usecase.ts
var GetRelatedProductsFromOrdersUseCase = class {
  constructor(prisma2) {
    this.prisma = prisma2;
  }
  async execute(userId, query) {
    const limitRaw = query.limit;
    const limit = typeof limitRaw === "number" && Number.isFinite(limitRaw) ? Math.min(Math.max(Math.floor(limitRaw), 1), 24) : 12;
    const purchased = await this.prisma.orderItem.findMany({
      where: {
        order: {
          userId,
          status: {
            in: ["CONFIRMED", "PAID", "SHIPPED", "DELIVERED", "RETURNED"]
          }
        }
      },
      select: {
        productId: true
      },
      distinct: ["productId"],
      take: 200
    });
    const purchasedProductIds = purchased.map((p) => p.productId).filter((id) => typeof id === "string" && id.length > 0);
    if (purchasedProductIds.length === 0) {
      return { products: [] };
    }
    const categoryLinks = await this.prisma.productCategory.findMany({
      where: {
        productId: { in: purchasedProductIds }
      },
      select: {
        categoryId: true
      },
      distinct: ["categoryId"],
      take: 50
    });
    const categoryIds = categoryLinks.map((c) => c.categoryId).filter((id) => typeof id === "string" && id.length > 0);
    if (categoryIds.length === 0) {
      return { products: [] };
    }
    const rows = await this.prisma.product.findMany({
      where: {
        isDeleted: false,
        categories: {
          some: {
            categoryId: { in: categoryIds }
          }
        },
        id: {
          notIn: purchasedProductIds
        }
      },
      take: limit,
      orderBy: [{ createdAt: "desc" }],
      select: {
        id: true,
        name: true,
        basePrice: true,
        isSale: true,
        variants: {
          where: { isDeleted: false },
          orderBy: { price: "asc" },
          take: 1,
          select: {
            price: true
          }
        },
        images: {
          orderBy: [{ isPrimary: "desc" }, { sortOrder: "asc" }],
          take: 1,
          select: {
            url: true
          }
        }
      }
    });
    const products = rows.map((row) => ({
      id: row.id,
      name: row.name,
      imageUrl: row.images[0]?.url ?? null,
      minPrice: Number(row.variants[0]?.price ?? row.basePrice),
      isNew: false,
      isSale: row.isSale ?? false
    }));
    return { products };
  }
};

