// src/module/product/applications/services/size-recommendation.service.ts
var SizeRecommendationService = class {
  constructor(prisma2) {
    this.prisma = prisma2;
  }
  async recommend(input) {
    if (!Number.isFinite(input.heightCm) || input.heightCm < 100 || input.heightCm > 230) {
      throw new BadRequestError("heightCm must be between 100 and 230");
    }
    if (!Number.isFinite(input.weightKg) || input.weightKg < 30 || input.weightKg > 250) {
      throw new BadRequestError("weightKg must be between 30 and 250");
    }
    const product = await this.prisma.product.findFirst({
      where: { id: input.productId, isDeleted: false },
      select: { productTypeId: true }
    });
    if (!product) throw new BadRequestError("Product not found");
    const rules = await this.prisma.sizeChartRule.findMany({
      where: {
        isActive: true,
        OR: [
          { productId: input.productId },
          { productId: null, productTypeId: product.productTypeId }
        ]
      },
      orderBy: [{ productId: "desc" }, { priority: "desc" }]
    });
    const matches = rules.filter((rule) => {
      const heightOk = (rule.minHeightCm === null || input.heightCm >= Number(rule.minHeightCm)) && (rule.maxHeightCm === null || input.heightCm <= Number(rule.maxHeightCm));
      const weightOk = (rule.minWeightKg === null || input.weightKg >= Number(rule.minWeightKg)) && (rule.maxWeightKg === null || input.weightKg <= Number(rule.maxWeightKg));
      return heightOk && weightOk && (!input.fitPreference || rule.fitPreference === input.fitPreference);
    });
    if (matches.length === 0) {
      return {
        recommendedSize: null,
        confidence: "LOW",
        alternatives: [],
        reason: "Ch\u01B0a c\xF3 quy t\u1EAFc size ph\xF9 h\u1EE3p v\u1EDBi s\u1ED1 \u0111o n\xE0y."
      };
    }
    return {
      recommendedSize: matches[0].sizeLabel,
      confidence: matches.length === 1 ? "HIGH" : "MEDIUM",
      alternatives: matches.slice(1, 3).map((rule) => rule.sizeLabel),
      reason: matches.length === 1 ? "\u0110\u1EC1 xu\u1EA5t d\u1EF1a tr\xEAn chi\u1EC1u cao, c\xE2n n\u1EB7ng v\xE0 ki\u1EC3u m\u1EB7c mong mu\u1ED1n." : "S\u1ED1 \u0111o n\u1EB1m g\u1EA7n ranh gi\u1EDBi nhi\u1EC1u size; b\u1EA1n n\xEAn xem th\xEAm b\u1EA3ng size."
    };
  }
};

// src/module/product/di.ts
function createProductModule() {
  const categoryRepository = new PrismaCategoryRepository(prisma);
  const productRepository = new PrismaProductRepository(prisma);
  const wishlistRepository = new PrismaWishlistRepository(prisma);
  const getCategoryStatsUseCase = new GetCategoryStatsUseCase(categoryRepository);
  const getCategoryShowcasesUseCase = new GetCategoryShowcasesUseCase(productRepository);
  const getProductsUseCase = new GetProductsUseCase(productRepository);
  const getProductDetailUseCase = new GetProductDetailUseCase(productRepository, prisma);
  const addProductFavoriteUseCase = new AddProductFavoriteUseCase(wishlistRepository);
  const removeProductFavoriteUseCase = new RemoveProductFavoriteUseCase(wishlistRepository);
  const getFavoriteProductsUseCase = new GetFavoriteProductsUseCase(wishlistRepository);
  const getRelatedProductsFromOrdersUseCase = new GetRelatedProductsFromOrdersUseCase(prisma);
  const getHomeTeamContentUseCase = new GetHomeTeamContentUseCase(productRepository);
  const controller = new ProductController(
    getCategoryStatsUseCase,
    getCategoryShowcasesUseCase,
    getProductsUseCase,
    getProductDetailUseCase,
    addProductFavoriteUseCase,
    removeProductFavoriteUseCase,
    getFavoriteProductsUseCase,
    getRelatedProductsFromOrdersUseCase,
    getHomeTeamContentUseCase
  );
  const productAPI = new ProductAPI(controller, new SizeRecommendationService(prisma));
  return productAPI.router;
}

