// src/module/common/interface-adapter/controller/public-products.controller.ts
var PublicProductsController = class {
  constructor(getProductsUseCase) {
    this.getProductsUseCase = getProductsUseCase;
  }
  async getProducts(req, res) {
    const page = req.query.page ? parseInt(req.query.page, 10) : void 0;
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : void 0;
    const getStringParam = (param) => {
      if (typeof param === "string") return param;
      if (Array.isArray(param) && param.length > 0) return param[0];
      return void 0;
    };
    const category = getStringParam(req.query.c);
    const size = getStringParam(req.query.s);
    const color = getStringParam(req.query.cl);
    const usageOccasion = getStringParam(req.query.uo) ?? getStringParam(req.query.usageOccasion);
    const priceRange = getStringParam(req.query.p);
    const sort = getStringParam(req.query.sort);
    const search = getStringParam(req.query.q) ?? getStringParam(req.query.search);
    if (search && search.length > 120) {
      throw new BadRequestError("search is too long");
    }
    const result = await this.getProductsUseCase.execute({
      page,
      limit,
      category,
      size,
      color,
      usageOccasion,
      priceRange,
      search,
      sort
    });
    res.status(200).json(ResponseFormatter.success(result, "Products retrieved successfully"));
  }
};

// src/module/common/di.ts
function createCommonModule() {
  const categoryRepository = new PrismaCategoryRepository3(prisma);
  const tagRepository = new PrismaTagRepository2(prisma);
  const productTypeSchemaRepository = new PrismaProductTypeSchemaRepository(prisma);
  const productRepository = new PrismaProductRepository(prisma);
  const getCategoriesUseCase = new GetCategoriesUseCase2(categoryRepository);
  const getTagsUseCase = new GetTagsUseCase2(tagRepository);
  const getProductTypeSchemaUseCase = new GetProductTypeSchemaUseCase(productTypeSchemaRepository);
  const getProductsUseCase = new GetProductsUseCase(productRepository);
  const commonController = new CommonController(
    getCategoriesUseCase,
    getTagsUseCase,
    getProductTypeSchemaUseCase
  );
  const publicProductsController = new PublicProductsController(getProductsUseCase);
  const commonAPI = new CommonAPI(commonController, publicProductsController);
  return commonAPI.router;
}

// src/module/cart/applications/errors/index.ts
var VariantRequiredError = class extends Error {
  constructor() {
    super("Vui l\xF2ng ch\u1ECDn ph\xE2n lo\u1EA1i s\u1EA3n ph\u1EA9m.");
    this.name = "VariantRequiredError";
  }
};
var VariantNotFoundError = class extends Error {
  constructor(variantId) {
    super(
      variantId ? `Ph\xE2n lo\u1EA1i ${variantId} kh\xF4ng t\u1ED3n t\u1EA1i ho\u1EB7c \u0111\xE3 b\u1ECB xo\xE1.` : "Ph\xE2n lo\u1EA1i s\u1EA3n ph\u1EA9m kh\xF4ng t\u1ED3n t\u1EA1i ho\u1EB7c \u0111\xE3 b\u1ECB xo\xE1."
    );
    this.name = "VariantNotFoundError";
  }
};
var ProductNotFoundError2 = class extends Error {
  constructor(productId) {
    super(
      productId ? `S\u1EA3n ph\u1EA9m ${productId} kh\xF4ng t\u1ED3n t\u1EA1i ho\u1EB7c \u0111\xE3 b\u1ECB xo\xE1.` : "S\u1EA3n ph\u1EA9m kh\xF4ng t\u1ED3n t\u1EA1i ho\u1EB7c \u0111\xE3 b\u1ECB xo\xE1."
    );
    this.name = "ProductNotFoundError";
  }
};
var InsufficientStockError = class extends Error {
  constructor(details) {
    super(
      `Kh\xF4ng \u0111\u1EE7 t\u1ED3n kho cho ph\xE2n lo\u1EA1i ${details.sku}. Y\xEAu c\u1EA7u: ${details.requested}, c\xF2n l\u1EA1i: ${details.available}.`
    );
    this.details = details;
    this.name = "InsufficientStockError";
  }
};
var ExceedsMaxQuantityError = class extends Error {
  constructor(details) {
    super(
      `Kh\xF4ng th\u1EC3 th\xEAm qu\xE1 ${details.maxQuantity} s\u1EA3n ph\u1EA9m cho c\xF9ng m\u1ED9t ph\xE2n lo\u1EA1i. Hi\u1EC7n c\xF3 trong gi\u1ECF: ${details.currentInCart}, y\xEAu c\u1EA7u th\xEAm: ${details.requested}.`
    );
    this.details = details;
    this.name = "ExceedsMaxQuantityError";
  }
};
var InvalidQuantityError = class extends Error {
  constructor(quantity) {
    super(`S\u1ED1 l\u01B0\u1EE3ng ph\u1EA3i t\u1EEB 1 \u0111\u1EBFn 10. Gi\xE1 tr\u1ECB nh\u1EADn \u0111\u01B0\u1EE3c: ${quantity}.`);
    this.name = "InvalidQuantityError";
  }
};
var CartItemNotFoundError = class extends Error {
  constructor(itemId) {
    super(itemId ? `Kh\xF4ng t\xECm th\u1EA5y s\u1EA3n ph\u1EA9m ${itemId} trong gi\u1ECF h\xE0ng.` : "Kh\xF4ng t\xECm th\u1EA5y s\u1EA3n ph\u1EA9m trong gi\u1ECF h\xE0ng.");
    this.name = "CartItemNotFoundError";
  }
};

// src/module/cart/applications/use-cases/add-to-cart.usecase.ts
var MAX_QUANTITY_PER_VARIANT = 10;
var AddToCartUseCase = class {
  constructor(cartRepository, variantRepository, productImageRepository) {
    this.cartRepository = cartRepository;
    this.variantRepository = variantRepository;
    this.productImageRepository = productImageRepository;
  }
  async execute(userId, command) {
    this.validateCommand(command);
    const variantWithProduct = await this.variantRepository.findByIdWithProduct(command.variantId);
    if (!variantWithProduct) {
      throw new VariantNotFoundError();
    }
    if (variantWithProduct.isDeleted) {
      throw new VariantNotFoundError();
    }
    if (variantWithProduct.product.isDeleted) {
      throw new ProductNotFoundError2();
    }
    let cart = await this.cartRepository.findByUserId(userId);
    if (!cart) {
      cart = await this.cartRepository.create(userId);
    }
    const existingItem = await this.cartRepository.findItem(
      cart.id,
      variantWithProduct.product.id,
      command.variantId
    );
    const currentQuantity = existingItem?.quantity || 0;
    const newQuantity = currentQuantity + command.quantity;
    const availableStock = variantWithProduct.stockAvailable;
    if (availableStock < newQuantity) {
      throw new InsufficientStockError({
        variantId: command.variantId,
        sku: variantWithProduct.sku,
        requested: newQuantity,
        available: availableStock
      });
    }
    if (newQuantity > MAX_QUANTITY_PER_VARIANT) {
      throw new ExceedsMaxQuantityError({
        maxQuantity: MAX_QUANTITY_PER_VARIANT,
        currentInCart: currentQuantity,
        requested: newQuantity
      });
    }
    if (existingItem) {
      await this.cartRepository.updateItemQuantity(existingItem.id, newQuantity);
    } else {
      await this.cartRepository.addItem({
        cartId: cart.id,
        productId: variantWithProduct.product.id,
        variantId: command.variantId,
        quantity: command.quantity
      });
    }
    const updatedCart = await this.cartRepository.getCartDetail(userId);
    if (!updatedCart) {
      throw new Error("Cart not found after update");
    }
    const cartDetailResult = {
      cartId: updatedCart.id,
      totalItems: updatedCart.totalItems,
      totalQuantity: updatedCart.totalQuantity,
      totalAmount: updatedCart.totalAmount,
      items: await Promise.all(
        updatedCart.items.map(async (item) => {
          const image = await this.productImageRepository.findImageForVariant(
            item.variantId,
            item.productId
          );
          return {
            itemId: item.id,
            productId: item.productId,
            productName: item.variantInfo.productName,
            variantId: item.variantId,
            variantSku: item.variantInfo.sku,
            variantAttributes: item.variantInfo.attributes,
            quantity: item.quantity,
            availableStock: item.variantInfo.stockAvailable,
            maxAllowedQuantity: Math.max(
              0,
              Math.min(item.variantInfo.stockAvailable, MAX_QUANTITY_PER_VARIANT)
            ),
            unitPrice: item.unitPrice,
            subtotal: item.subtotal,
            image: image ? {
              url: image.url,
              altText: image.altText || item.variantInfo.productName
            } : void 0
          };
        })
      )
    };
    return cartDetailResult;
  }
  validateCommand(command) {
    if (!command.variantId || command.variantId.trim() === "") {
      throw new VariantRequiredError();
    }
    if (!Number.isInteger(command.quantity) || command.quantity <= 0) {
      throw new InvalidQuantityError(command.quantity);
    }
  }
};

