// src/module/address/applications/services/user-shipping-info.service.ts
var REDIS_TTL_SECONDS = 30 * 24 * 60 * 60;
function cacheKey(userId) {
  return `user:${userId}:shipping:last`;
}
function normalizePhone(value) {
  return value.replace(/\s+/g, "").trim();
}
function normalizeInput(input) {
  return {
    recipient: input.recipient.trim(),
    phone: normalizePhone(input.phone),
    addressLine: input.addressLine.trim(),
    ward: input.ward.trim(),
    district: input.district.trim(),
    city: input.city.trim(),
    ghnProvinceId: input.ghnProvinceId,
    ghnDistrictId: input.ghnDistrictId,
    ghnWardCode: input.ghnWardCode?.trim() || void 0
  };
}
function isValidCached(payload) {
  if (!payload || typeof payload !== "object") return false;
  const obj = payload;
  return typeof obj.addressId === "string" && typeof obj.recipient === "string" && typeof obj.phone === "string" && typeof obj.addressLine === "string" && typeof obj.ward === "string" && typeof obj.district === "string" && typeof obj.city === "string";
}
var UserShippingInfoService = class {
  constructor(addressRepository, redis2) {
    this.addressRepository = addressRepository;
    this.redis = redis2;
  }
  async getLastUsedAddress(userId) {
    const raw3 = await this.redis.get(cacheKey(userId));
    if (raw3) {
      try {
        const parsed = JSON.parse(raw3);
        if (isValidCached(parsed)) {
          const fromDb = await this.addressRepository.findById(userId, parsed.addressId);
          if (fromDb) {
            return fromDb;
          }
        }
      } catch {
      }
    }
    const fallback = await this.addressRepository.findDefaultOrLatestByUserId(userId);
    if (fallback) {
      await this.rememberAddress(userId, {
        recipient: fallback.recipient,
        phone: fallback.phone,
        addressLine: fallback.addressLine,
        ward: fallback.ward,
        district: fallback.district,
        city: fallback.city,
        ghnProvinceId: fallback.ghnProvinceId ?? void 0,
        ghnDistrictId: fallback.ghnDistrictId ?? void 0,
        ghnWardCode: fallback.ghnWardCode ?? void 0
      });
    }
    return fallback;
  }
  async rememberAddress(userId, input) {
    const normalized = normalizeInput(input);
    const existing = await this.addressRepository.findMatchingByUserId(userId, normalized);
    const address = existing ?? await this.addressRepository.createForUser(userId, {
      ...normalized,
      isDefault: await this.addressRepository.countByUserId(userId) === 0
    });
    const payload = {
      addressId: address.id,
      ...normalized
    };
    await this.redis.set(cacheKey(userId), JSON.stringify(payload), "EX", REDIS_TTL_SECONDS);
    return address;
  }
};

// src/module/address/di.ts
function createUserShippingInfoService() {
  const addressRepository = new PrismaAddressRepository(prisma);
  return new UserShippingInfoService(addressRepository, redis);
}
function createAddressModule() {
  const addressRepository = new PrismaAddressRepository(prisma);
  const getMyAddressesUseCase = new GetMyAddressesUseCase(addressRepository);
  const shippingInfoService = new UserShippingInfoService(addressRepository, redis);
  const getLastUsedAddressUseCase = new GetLastUsedAddressUseCase(shippingInfoService);
  const addressController = new AddressController(getMyAddressesUseCase, getLastUsedAddressUseCase);
  const addressAPI = new AddressAPI(addressController);
  return addressAPI.router;
}

// src/infrastructure/messaging/rabbitmq.service.ts
import amqp from "amqplib";
var logger10 = createLogger("RabbitMQService");
var RABBITMQ_URL = process.env.RABBITMQ_URL || "amqp://rabbitmq:5672";
var PAYMENT_EVENTS_EXCHANGE = process.env.RABBITMQ_PAYMENT_EXCHANGE || "shop_events";
var PAYMENT_SUCCESS_ROUTING_KEY = process.env.RABBITMQ_PAYMENT_SUCCESS_ROUTING_KEY || "order.payment.success";
var PAYMENT_SUCCESS_QUEUE = process.env.RABBITMQ_ADMIN_NOTIFICATION_QUEUE || "admin_notification_q";
var PAYMENT_SUCCESS_DLX = process.env.RABBITMQ_ADMIN_NOTIFICATION_DLX || "admin_notification_dlx";
var PAYMENT_SUCCESS_DLQ = process.env.RABBITMQ_ADMIN_NOTIFICATION_DLQ || "admin_notification_dlq";
var RabbitMQService = class {
  connection = null;
  channel = null;
  consumeStarted = false;
  async getChannel() {
    if (this.channel) {
      return this.channel;
    }
    const connection = await amqp.connect(RABBITMQ_URL);
    this.connection = connection;
    connection.on("close", () => {
      logger10.warn("RabbitMQ connection closed");
      this.connection = null;
      this.channel = null;
      this.consumeStarted = false;
    });
    connection.on("error", (error) => {
      logger10.error("RabbitMQ connection error", {
        error: error instanceof Error ? error.message : String(error)
      });
    });
    const channel = await connection.createChannel();
    this.channel = channel;
    await channel.prefetch(10);
    await this.setupTopology(channel);
    logger10.info("RabbitMQ channel initialized", {
      exchange: PAYMENT_EVENTS_EXCHANGE,
      queue: PAYMENT_SUCCESS_QUEUE,
      dlq: PAYMENT_SUCCESS_DLQ
    });
    return channel;
  }
  async setupTopology(channel) {
    await channel.assertExchange(PAYMENT_EVENTS_EXCHANGE, "topic", { durable: true });
    await channel.assertExchange(PAYMENT_SUCCESS_DLX, "topic", { durable: true });
    await channel.assertQueue(PAYMENT_SUCCESS_DLQ, { durable: true });
    await channel.bindQueue(PAYMENT_SUCCESS_DLQ, PAYMENT_SUCCESS_DLX, PAYMENT_SUCCESS_ROUTING_KEY);
    await channel.assertQueue(PAYMENT_SUCCESS_QUEUE, {
      durable: true,
      deadLetterExchange: PAYMENT_SUCCESS_DLX,
      deadLetterRoutingKey: PAYMENT_SUCCESS_ROUTING_KEY
    });
    await channel.bindQueue(
      PAYMENT_SUCCESS_QUEUE,
      PAYMENT_EVENTS_EXCHANGE,
      PAYMENT_SUCCESS_ROUTING_KEY
    );
  }
  async publishPaymentSuccess(event) {
    const channel = await this.getChannel();
    const payload = Buffer.from(JSON.stringify(event));
    const ok = channel.publish(PAYMENT_EVENTS_EXCHANGE, PAYMENT_SUCCESS_ROUTING_KEY, payload, {
      contentType: "application/json",
      deliveryMode: 2,
      timestamp: Date.now()
    });
    if (!ok) {
      logger10.warn("RabbitMQ publish buffer full, message queued in memory");
    }
  }
  async consumePaymentSuccess(handler) {
    if (this.consumeStarted) {
      return;
    }
    const channel = await this.getChannel();
    this.consumeStarted = true;
    await channel.consume(PAYMENT_SUCCESS_QUEUE, async (msg) => {
      if (!msg) return;
      try {
        const payload = JSON.parse(msg.content.toString());
        await handler(payload);
        channel.ack(msg);
      } catch (error) {
        logger10.error("RabbitMQ consumer failed to process message", {
          error: error instanceof Error ? error.message : String(error)
        });
        channel.nack(msg, false, false);
      }
    });
    logger10.info("RabbitMQ consumer started", {
      queue: PAYMENT_SUCCESS_QUEUE
    });
  }
};
var rabbitMQService = new RabbitMQService();

// src/module/admin/notifications/infrastructure/services/admin-payment-notification.processor.ts
var logger11 = createLogger("AdminPaymentNotificationProcessor");
var AdminPaymentNotificationProcessor = class {
  constructor(prisma2) {
    this.prisma = prisma2;
  }
  async process(input) {
    const dedupeKey = `notify:admin:payment-success:${input.orderId}`;
    const lockResult = await redis.set(
      dedupeKey,
      input.paidAt.toISOString(),
      "EX",
      60 * 60 * 24 * 7,
      "NX"
    );
    if (lockResult !== "OK") {
      return false;
    }
    try {
      const admins = await this.prisma.userRole.findMany({
        where: {
          role: {
            code: "ADMIN"
          }
        },
        select: {
          userId: true
        },
        distinct: ["userId"]
      });
      if (admins.length === 0) {
        return false;
      }
      const amountText = new Intl.NumberFormat("vi-VN").format(input.amount);
      const content = `\u0110\u01A1n h\xE0ng #${input.orderCode} \u0111\xE3 thanh to\xE1n th\xE0nh c\xF4ng (${amountText} VND)`;
      const createdRows = await this.prisma.$transaction(
        admins.map(
          (admin) => this.prisma.notification.create({
            data: {
              userId: admin.userId,
              content,
              isRead: false
            },
            select: {
              id: true,
              content: true,
              isRead: true,
              createdAt: true,
              userId: true
            }
          })
        )
      );
      for (const row of createdRows) {
        adminNotificationHub.sendPaymentSuccess(row.userId, {
          id: row.id,
          content: row.content,
          isRead: row.isRead,
          createdAt: row.createdAt.toISOString()
        });
      }
      await this.prisma.auditLog.create({
        data: {
          actorType: "SYSTEM",
          targetType: "Order",
          targetId: input.orderId,
          action: "ADMIN_PAYMENT_NOTIFICATION_SENT",
          newData: {
            orderCode: input.orderCode,
            amount: input.amount,
            paidAt: input.paidAt,
            receivers: createdRows.length
          }
        }
      });
      logger11.info("Admin notifications sent for paid order", {
        orderCode: input.orderCode,
        receivers: createdRows.length
      });
      return true;
    } catch (error) {
      await redis.del(dedupeKey);
      throw error;
    }
  }
};

