import express35 from "express";

// src/module/location/infrastructure/vietnam-locations.store.ts
import { access, readFile } from "fs/promises";
import { join as join3 } from "path";
var cached2 = null;
function getCandidatePaths() {
  const cwd = process.cwd();
  return [
    // Development and existing local runtime.
    join3(cwd, "src", "resources", "vietnam-locations", "nested-divisions.json"),
    // Production Docker runtime (copied as /app/resources).
    join3(cwd, "resources", "vietnam-locations", "nested-divisions.json"),
    // Optional fallback if resources are copied under dist.
    join3(cwd, "dist", "resources", "vietnam-locations", "nested-divisions.json")
  ];
}
async function resolveDataPath() {
  const candidates = getCandidatePaths();
  for (const candidate of candidates) {
    try {
      await access(candidate);
      return candidate;
    } catch {
    }
  }
  throw new Error(`Vietnam locations data file not found. Checked paths: ${candidates.join(", ")}`);
}
async function loadVietnamLocations() {
  if (cached2) return cached2;
  const dataPath = await resolveDataPath();
  const raw3 = await readFile(dataPath, "utf8");
  const parsed = JSON.parse(raw3);
  if (!Array.isArray(parsed)) {
    throw new Error("Invalid vietnam locations json: expected array");
  }
  cached2 = parsed;
  return cached2;
}

// src/module/location/infrastructure/api/location.api.ts
var LocationAPI = class {
  router = express35.Router();
  constructor() {
    this.initializeRoutes();
  }
  initializeRoutes() {
    this.router.get("/provinces", asyncHandler(this.getProvinces.bind(this)));
    this.router.get("/wards", asyncHandler(this.getWardsByProvince.bind(this)));
  }
  async getProvinces(_req, res) {
    const provinces = await loadVietnamLocations();
    const items = provinces.map((p) => ({ code: p.code, name: p.name })).sort((a, b) => a.name.localeCompare(b.name, "vi"));
    res.status(200).json(ResponseFormatter.success({ items }));
  }
  async getWardsByProvince(req, res) {
    const provinceCodeRaw = String(req.query.provinceCode ?? "").trim();
    const provinceCode = Number(provinceCodeRaw);
    if (!Number.isFinite(provinceCode)) {
      throw new BadRequestError("provinceCode is required");
    }
    const provinces = await loadVietnamLocations();
    const province = provinces.find((p) => p.code === provinceCode);
    if (!province) {
      throw new BadRequestError("province not found");
    }
    const items = [...province.wards ?? []].map((w) => ({ code: w.code, name: w.name })).sort((a, b) => a.name.localeCompare(b.name, "vi"));
    res.status(200).json(ResponseFormatter.success({ items }));
  }
};

