// src/server.ts
import dotenv3 from "dotenv";
var logger24 = createLogger("Server");
var env2 = process.env.NODE_ENV || "development";
dotenv3.config({
  path: `.env.${env2}`
});
var PORT = process.env.PORT || 8e3;
var HOST = process.env.HOST || "0.0.0.0";
app_default.listen(Number(PORT), HOST, () => {
  logger24.info(`Server listening on ${HOST}:${PORT}`, {
    environment: env2,
    port: PORT,
    host: HOST
  });
});
